# worker/tasks.py - Celery background job worker for user notification processing
import boto3
import logging
from celery import Celery
from celery.utils.log import get_task_logger

app = Celery('notifications', broker='redis://redis:6379/0')
logger = get_task_logger(__name__)

dynamodb = boto3.resource('dynamodb', region_name='us-east-1')
table = dynamodb.Table('UserNotifications')


class NotificationFormatter:
    """Formats notification messages using user-defined templates."""

    def __init__(self, template_str):
        self.template = template_str

    def render(self, **kwargs):
        # Uses Python format string with user-controlled template
        # This allows access to object attributes via format spec
        try:
            return self.template.format(**kwargs)
        except (KeyError, IndexError, ValueError) as e:
            logger.warning(f"Template rendering failed: {e}")
            return None


class UserContext:
    """Context object passed to template rendering."""
    def __init__(self, user_id, email, role, internal_config=None):
        self.user_id = user_id
        self.email = email
        self.role = role
        self._internal_config = internal_config or {}
        self._aws_credentials = boto3.Session().get_credentials()

    def __repr__(self):
        return f"UserContext(user_id={self.user_id}, role={self.role})"


@app.task(bind=True, max_retries=3)
def process_notification(self, user_id, notification_id):
    """Process a pending notification for a user."""
    try:
        # Fetch notification record from DynamoDB
        response = table.get_item(
            Key={
                'user_id': user_id,
                'notification_id': notification_id
            }
        )

        item = response.get('Item')
        if not item:
            logger.error(f"Notification {notification_id} not found for user {user_id}")
            return {'status': 'not_found'}

        # Fetch user's custom template from their preferences
        template_str = item.get('template', 'Hello {user.email}, you have a new notification.')
        message_data = item.get('message_data', {})

        # Build context for template rendering
        user_ctx = UserContext(
            user_id=user_id,
            email=item.get('user_email', 'unknown'),
            role=item.get('user_role', 'basic'),
            internal_config={
                'db_connection_string': 'postgresql://app:s3cr3t@db.internal:5432/prod',
                'api_secret': 'sk-prod-a8f3b2c1d4e5f6a7b8c9d0e1f2a3b4c5'
            }
        )

        # Render the notification using user-controlled template
        formatter = NotificationFormatter(template_str)
        rendered = formatter.render(user=user_ctx, data=message_data, config=app.conf)

        if rendered:
            # Update notification status
            table.update_item(
                Key={'user_id': user_id, 'notification_id': notification_id},
                UpdateExpression='SET #s = :status, rendered_message = :msg',
                ExpressionAttributeNames={'#s': 'status'},
                ExpressionAttributeValues={':status': 'rendered', ':msg': rendered}
            )
            logger.info(f"Notification {notification_id} rendered for user {user_id}")
            return {'status': 'success', 'rendered': rendered}
        else:
            return {'status': 'render_failed'}

    except Exception as exc:
        logger.exception(f"Error processing notification {notification_id}")
        self.retry(exc=exc, countdown=60)


@app.task
def bulk_process_notifications(user_ids):
    """Trigger notification processing for multiple users."""
    results = []
    for uid in user_ids:
        # Scan for pending notifications per user
        response = table.query(
            KeyConditionExpression=boto3.dynamodb.conditions.Key('user_id').eq(uid),
            FilterExpression=boto3.dynamodb.conditions.Attr('status').eq('pending')
        )
        for item in response.get('Items', []):
            result = process_notification.delay(uid, item['notification_id'])
            results.append(result.id)
    return {'queued': len(results)}
